public sealed class MqHandlerDispatchTests
{
    [Fact]
    public void EveryHandledEventHasADispatchMethod()
    {
        var expected = new[]
        {
            "HandleProductCreatedAsync",
            "HandleInventoryUpdatedAsync",
            "HandleInventoryReservedAsync",
            "HandleInventoryReleasedAsync",
            "HandleOrderConfirmedAsync",
            "HandleOrderCancelledAsync",
        };
        foreach (var handlerName in expected)
        {
            var method = typeof(MqConsumerService).GetMethod(
                handlerName, BindingFlags.Instance | BindingFlags.NonPublic);
            Assert.True(method is not null, $"Missing dispatch handler method: {handlerName}");
        }
    }

    [Fact]
    public void HandleProductCreatedAsync_HasExpectedPayloadParameter()
    {
        var method = typeof(MqConsumerService).GetMethod(
            "HandleProductCreatedAsync", BindingFlags.Instance | BindingFlags.NonPublic);
        Assert.NotNull(method);
        var parameters = method!.GetParameters();
        Assert.Single(parameters);
        Assert.Equal(typeof(ProductCreatedPayload), parameters[0].ParameterType);
    }

